WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    try { if (typeof hmFS !== 'undefined') variantIdx = Number(hmFS.SysProGetInt('dialcraft_variant')) || 0 } catch (e) {}

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Waterfall (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      src: A('wf/bg.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(79),
      minute_startY: px(222),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_464y,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(79),
      hour_startY: px(62),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Main_46k4,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Spray (IMG)
    const variants_0 = [A('wf/fx/spray_00.png'), A('wf/fx/spray_01.png'), A('wf/fx/spray_02.png'), A('wf/fx/spray_03.png'), A('wf/fx/spray_04.png'), A('wf/fx/spray_05.png'), A('wf/fx/spray_06.png'), A('wf/fx/spray_07.png'), A('wf/fx/spray_08.png'), A('wf/fx/spray_09.png'), A('wf/fx/spray_10.png'), A('wf/fx/spray_11.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.spray = variant_0
    F.spray = variants_0

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(73),
      y: px(411),
      week_en: img_Weekday_4687,
      week_sc: img_Weekday_4687,
      week_tc: img_Weekday_4687,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Dot (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(106),
      y: px(412),
      w: px(5),
      h: px(5),
      src: A('wf/ui/dot.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(115),
      day_startY: px(411),
      day_zero: 1,
      day_space: px(0),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_45o9,
      day_sc_array: img_Day_45o9,
      day_tc_array: img_Day_45o9,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Month (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      month_startX: px(137),
      month_startY: px(411),
      month_zero: 0,
      month_space: px(0),
      month_align: ui.align.LEFT,
      month_follow: 0,
      month_is_character: true,
      month_en_array: img_Month_42yg,
      month_sc_array: img_Month_42yg,
      month_tc_array: img_Month_42yg,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Heart icon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(181),
      y: px(411),
      w: px(13),
      h: px(13),
      src: A('wf/ui/heart.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Heart rate (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(197),
      y: px(411),
      w: px(27),
      type: ui.data_type.HEART,
      font_array: img_Day_45o9,
      align_h: ui.align.RIGHT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // BPM label (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(228),
      y: px(413),
      w: px(20),
      h: px(20),
      src: A('wf/ui/bpm.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Step icon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(264),
      y: px(411),
      w: px(14),
      h: px(14),
      src: A('wf/ui/foot.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(281),
      y: px(411),
      w: px(45),
      type: ui.data_type.STEP,
      font_array: img_Day_45o9,
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(126),
      minute_startY: px(229),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_AOD_43i4,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Hour AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(126),
      hour_startY: px(139),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_AOD_43i4,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length)
      try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt('dialcraft_variant', variantIdx) } catch (e) {}
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // the spray loop: 12 frames at 10 fps, restarting on every minute for variety
      const MS = 55, NF = 12, FRAME_MS = 100;
      let idx = 0, last = -1, id = null, pausedAt = 0;
      const tick = () => {
        const now = Date.now();
        const i = Math.floor((now % (NF * FRAME_MS)) / FRAME_MS) % NF;
        if (i !== last) {
          last = i;
          W.spray.setProperty(ui.prop.MORE, { x: pxv(0), y: pxv(0), src: F.spray[i] });
        }
      };
      const safe = () => { try { tick(); } catch (e) {} };
      const start = () => {
        if (id === null) { try { id = setInterval(safe, MS); } catch (e) {} }
        safe();
      };
      const stop = () => {
        if (id !== null) { try { clearInterval(id); } catch (e) {} id = null; }
        pausedAt = Date.now();
      };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
      safe();
      start();
    }
  },

  build() {
    this.initView()
  },
})
